                List files = (List)transferable.getTransferData(flavor);
                for (File file : files) {
                    dragData.addFile(file.getPath(), file.getName());
                }
            }
            catch (Exception e) {
                e.printStackTrace();
            }
        }
        return dragData;
    }
}

